import json
import re
import datetime
from urllib.parse import parse_qs

_entries = []
_next_id = 1

_MONTH_RE = re.compile(r'^\d{4}-(0[1-9]|1[0-2])$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _err(status, msg):
    return status, {"error": msg}


def _public(e):
    return {
        "id": e["id"],
        "type": e["type"],
        "amount": e["amount"],
        "category": e["category"],
        "date": e["date"],
        "note": e["note"],
    }


def _parse_body(body):
    if body is None or len(body.strip()) == 0:
        return None, None
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return None, "請求內容不是有效的 JSON"
    return data, None


def _validate(data):
    if not isinstance(data, dict):
        return None, "請求內容必須是 JSON 物件"
    t = data.get("type")
    if t not in ("income", "expense"):
        return None, "類型必須為 income 或 expense"
    amount = data.get("amount")
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        return None, "金額必須為正整數"
    category = data.get("category")
    if not isinstance(category, str) or not category.strip():
        return None, "分類不可為空"
    date = data.get("date")
    ok = isinstance(date, str) and _DATE_RE.match(date) is not None
    if ok:
        try:
            datetime.datetime.strptime(date, "%Y-%m-%d")
        except ValueError:
            ok = False
    if not ok:
        return None, "日期格式必須為有效的 YYYY-MM-DD"
    note = data.get("note", "")
    if note is None:
        note = ""
    if not isinstance(note, str):
        return None, "備註必須為文字"
    return {
        "type": t,
        "amount": amount,
        "category": category.strip(),
        "date": date,
        "note": note,
    }, None


def _get_month(query, data):
    month = None
    if query:
        vals = parse_qs(query).get("month")
        if vals:
            month = vals[0]
    if month is None and isinstance(data, dict) and "month" in data:
        month = data.get("month")
    if month is None or month == "":
        return datetime.date.today().strftime("%Y-%m"), None
    if not isinstance(month, str) or not _MONTH_RE.match(month):
        return None, "月份格式必須為 YYYY-MM"
    return month, None


def _find(entry_id):
    for e in _entries:
        if e["id"] == entry_id:
            return e
    return None


def _list_entries(query, data):
    month, err = _get_month(query, data)
    if err:
        return _err(400, err)
    items = [e for e in _entries if e["date"].startswith(month)]
    items.sort(key=lambda e: (e["date"], int(e["id"])), reverse=True)
    return 200, {"items": [_public(e) for e in items]}


def _create(data):
    global _next_id
    if data is None:
        return _err(400, "請求內容不可為空")
    clean, err = _validate(data)
    if err:
        return _err(400, err)
    clean["id"] = str(_next_id)
    _next_id += 1
    _entries.append(clean)
    return 201, _public(clean)


def _update(entry_id, data):
    e = _find(entry_id)
    if e is None:
        return _err(404, "找不到指定的明細")
    if data is None:
        return _err(400, "請求內容不可為空")
    clean, err = _validate(data)
    if err:
        return _err(400, err)
    e.update(clean)
    return 200, _public(e)


def _delete(entry_id):
    e = _find(entry_id)
    if e is None:
        return _err(404, "找不到指定的明細")
    _entries.remove(e)
    return 200, {"id": entry_id, "deleted": True}


def _summary(query, data):
    month, err = _get_month(query, data)
    if err:
        return _err(400, err)
    income = 0
    expense = 0
    groups = {}
    for e in _entries:
        if not e["date"].startswith(month):
            continue
        if e["type"] == "income":
            income += e["amount"]
        else:
            expense += e["amount"]
        key = (e["type"], e["category"])
        groups[key] = groups.get(key, 0) + e["amount"]
    items = [{"type": k[0], "category": k[1], "total": v} for k, v in groups.items()]
    items.sort(key=lambda x: (x["type"], -x["total"], x["category"]))
    return 200, {
        "month": month,
        "income_total": income,
        "expense_total": expense,
        "balance": income - expense,
        "items": items,
    }


def handle(method, path, body):
    try:
        method = (method or "").upper()
        query = ""
        if "?" in path:
            path, query = path.split("?", 1)
        if len(path) > 1:
            path = path.rstrip("/")
        if not path.startswith("/"):
            path = "/" + path
        segments = [s for s in path.split("/") if s != ""]

        if segments == ["entries"]:
            if method == "GET":
                data, err = _parse_body(body)
                if err:
                    data = None
                return _list_entries(query, data)
            if method == "POST":
                data, err = _parse_body(body)
                if err:
                    return _err(400, err)
                return _create(data)
            return _err(405, "不支援此方法")

        if len(segments) == 2 and segments[0] == "entries":
            entry_id = segments[1]
            if method == "PUT":
                data, err = _parse_body(body)
                if err:
                    return _err(400, err)
                return _update(entry_id, data)
            if method == "DELETE":
                return _delete(entry_id)
            return _err(405, "不支援此方法")

        if segments == ["summary"]:
            if method == "GET":
                data, err = _parse_body(body)
                if err:
                    data = None
                return _summary(query, data)
            return _err(405, "不支援此方法")

        return _err(404, "找不到此路徑")
    except Exception:
        return _err(500, "伺服器發生錯誤")

