(function () {
  'use strict';

  var PRESETS = ['餐飲', '交通', '購物', '娛樂', '薪資', '獎金'];
  var TYPE_LABEL = { income: '收入', expense: '支出' };

  var state = { month: '', entries: [], editingId: null };

  var $ = function (id) { return document.getElementById(id); };
  var els = {
    error: $('error'),
    month: $('month'),
    incomeTotal: $('income-total'),
    expenseTotal: $('expense-total'),
    balance: $('balance'),
    incomeCats: $('income-cats'),
    expenseCats: $('expense-cats'),
    form: $('entry-form'),
    formTitle: $('form-title'),
    type: $('type'),
    amount: $('amount'),
    category: $('category'),
    date: $('date'),
    note: $('note'),
    submitBtn: $('submit-btn'),
    cancelBtn: $('cancel-btn'),
    body: $('entries-body'),
    empty: $('empty'),
    categoryList: $('category-list')
  };

  function showError(msg) {
    els.error.textContent = msg;
    els.error.hidden = false;
  }

  function clearError() {
    els.error.textContent = '';
    els.error.hidden = true;
  }

  function fmt(n) {
    var v = Number(n);
    if (!isFinite(v)) { return String(n); }
    return v.toLocaleString('zh-TW');
  }

  // 明細列表用的千分位格式（固定以逗號分隔，只影響顯示）
  function fmtThousands(n) {
    var v = Number(n);
    if (!isFinite(v)) { return String(n); }
    var neg = v < 0;
    var s = String(Math.abs(Math.trunc(v)));
    if (/e/i.test(s)) { return fmt(v); }
    s = s.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return (neg ? '-' : '') + s;
  }

  // 統一的 API 呼叫；失敗時丟出帶有訊息的 Error
  function api(method, path, body) {
    var opts = { method: method, headers: {} };
    if (body !== undefined) {
      opts.headers['Content-Type'] = 'application/json';
      opts.body = JSON.stringify(body);
    }
    return fetch(path, opts).then(function (res) {
      return res.text().then(function (text) {
        var data = null;
        try { data = text ? JSON.parse(text) : null; } catch (e) { data = null; }
        if (!res.ok) {
          var msg = data && data.error ? data.error : ('HTTP ' + res.status);
          throw new Error(typeof msg === 'string' ? msg : JSON.stringify(msg));
        }
        if (data === null || typeof data !== 'object') {
          throw new Error('伺服器回應格式不正確');
        }
        return data;
      });
    }, function () {
      throw new Error('無法連線到伺服器');
    });
  }

  function reportError(err) {
    showError('發生錯誤：' + (err && err.message ? err.message : String(err)));
  }

  function todayString() {
    var d = new Date();
    var m = String(d.getMonth() + 1).padStart(2, '0');
    var day = String(d.getDate()).padStart(2, '0');
    return d.getFullYear() + '-' + m + '-' + day;
  }

  function defaultDateForMonth() {
    var t = todayString();
    if (state.month && t.slice(0, 7) !== state.month) {
      return state.month + '-01';
    }
    return t;
  }

  /* ---------- 分類預設 ---------- */
  function initPresets() {
    PRESETS.forEach(function (c) {
      var o = document.createElement('option');
      o.value = c;
      els.categoryList.appendChild(o);
    });
  }

  /* ---------- 摘要 ---------- */
  function renderCats(ul, items) {
    ul.textContent = '';
    if (!items.length) {
      var li = document.createElement('li');
      li.className = 'muted';
      li.textContent = '無資料';
      ul.appendChild(li);
      return;
    }
    items.forEach(function (it) {
      var li = document.createElement('li');
      var name = document.createElement('span');
      name.textContent = it.category;
      var val = document.createElement('span');
      val.textContent = fmt(it.total);
      li.appendChild(name);
      li.appendChild(val);
      ul.appendChild(li);
    });
  }

  function renderSummary(s) {
    els.incomeTotal.textContent = fmt(s.income_total);
    els.expenseTotal.textContent = fmt(s.expense_total);
    var bal = Number(s.balance);
    els.balance.textContent = (bal > 0 ? '+' : '') + fmt(bal);
    els.balance.className = bal < 0 ? 'neg' : (bal > 0 ? 'pos' : '');
    var items = Array.isArray(s.items) ? s.items : [];
    renderCats(els.incomeCats, items.filter(function (i) { return i.type === 'income'; }));
    renderCats(els.expenseCats, items.filter(function (i) { return i.type === 'expense'; }));
  }

  /* ---------- 列表 ---------- */
  function renderEntries() {
    els.body.textContent = '';
    els.empty.hidden = state.entries.length > 0;
    state.entries.forEach(function (e) {
      var tr = document.createElement('tr');

      var tdDate = document.createElement('td');
      tdDate.textContent = e.date;
      tr.appendChild(tdDate);

      var tdType = document.createElement('td');
      var badge = document.createElement('span');
      badge.className = 'badge ' + (e.type === 'income' ? 'income' : 'expense');
      badge.textContent = TYPE_LABEL[e.type] || e.type;
      tdType.appendChild(badge);
      tr.appendChild(tdType);

      var tdCat = document.createElement('td');
      tdCat.textContent = e.category;
      tr.appendChild(tdCat);

      var tdAmt = document.createElement('td');
      tdAmt.className = 'num';
      tdAmt.textContent = fmtThousands(e.amount);
      tr.appendChild(tdAmt);

      var tdNote = document.createElement('td');
      tdNote.textContent = e.note || '';
      tr.appendChild(tdNote);

      var tdOps = document.createElement('td');
      tdOps.className = 'ops';
      var edit = document.createElement('button');
      edit.type = 'button';
      edit.className = 'small';
      edit.textContent = '編輯';
      edit.addEventListener('click', function () { startEdit(e); });
      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'small danger';
      del.textContent = '刪除';
      del.addEventListener('click', function () { removeEntry(e); });
      tdOps.appendChild(edit);
      tdOps.appendChild(del);
      tr.appendChild(tdOps);

      els.body.appendChild(tr);
    });
  }

  function monthQuery() {
    return '?month=' + encodeURIComponent(state.month);
  }

  function loadEntries() {
    return api('GET', 'api/entries' + monthQuery()).then(function (data) {
      state.entries = Array.isArray(data.items) ? data.items : [];
      renderEntries();
    });
  }

  function loadSummary() {
    return api('GET', 'api/summary' + monthQuery()).then(renderSummary);
  }

  function reload() {
    return Promise.all([loadEntries(), loadSummary()]);
  }

  /* ---------- 表單 ---------- */
  function resetForm() {
    state.editingId = null;
    els.type.value = 'expense';
    els.amount.value = '';
    els.category.value = '';
    els.date.value = defaultDateForMonth();
    els.note.value = '';
    els.formTitle.textContent = '新增明細';
    els.submitBtn.textContent = '新增';
    els.cancelBtn.hidden = true;
  }

  function startEdit(e) {
    clearError();
    state.editingId = e.id;
    els.type.value = e.type;
    els.amount.value = e.amount;
    els.category.value = e.category;
    els.date.value = e.date;
    els.note.value = e.note || '';
    els.formTitle.textContent = '編輯明細';
    els.submitBtn.textContent = '儲存修改';
    els.cancelBtn.hidden = false;
    els.form.scrollIntoView({ behavior: 'smooth', block: 'start' });
    els.amount.focus();
  }

  function readForm() {
    var raw = els.amount.value.trim();
    var amount = /^\d+$/.test(raw) ? parseInt(raw, 10) : NaN;
    if (!(amount > 0)) {
      throw new Error('金額必須是正整數');
    }
    var category = els.category.value.trim();
    if (!category) {
      throw new Error('請輸入分類');
    }
    var date = els.date.value;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      throw new Error('請選擇有效的日期（YYYY-MM-DD）');
    }
    return {
      type: els.type.value === 'income' ? 'income' : 'expense',
      amount: amount,
      category: category,
      date: date,
      note: els.note.value.trim()
    };
  }

  function onSubmit(ev) {
    ev.preventDefault();
    clearError();
    var payload;
    try {
      payload = readForm();
    } catch (err) {
      showError('發生錯誤：' + err.message);
      return;
    }
    var editing = state.editingId;
    var req = editing === null
      ? api('POST', 'api/entries', payload)
      : api('PUT', 'api/entries/' + encodeURIComponent(editing), payload);
    els.submitBtn.disabled = true;
    req.then(function () {
      resetForm();
      return reload();
    }).catch(reportError).then(function () {
      els.submitBtn.disabled = false;
    });
  }

  function removeEntry(e) {
    var label = e.date + ' ' + e.category + ' ' + fmtThousands(e.amount);
    if (!window.confirm('確定要刪除這筆明細嗎？\n' + label)) { return; }
    clearError();
    api('DELETE', 'api/entries/' + encodeURIComponent(e.id)).then(function () {
      if (state.editingId !== null && String(state.editingId) === String(e.id)) {
        resetForm();
      }
      return reload();
    }).catch(reportError);
  }

  /* ---------- 月份切換 ---------- */
  function onMonthChange() {
    var v = els.month.value;
    if (!/^\d{4}-\d{2}$/.test(v)) { return; }
    state.month = v;
    clearError();
    if (state.editingId === null) {
      els.date.value = defaultDateForMonth();
    }
    reload().catch(reportError);
  }

  /* ---------- 初始化 ---------- */
  function init() {
    initPresets();
    els.form.addEventListener('submit', onSubmit);
    els.cancelBtn.addEventListener('click', function () {
      clearError();
      resetForm();
    });
    els.month.addEventListener('change', onMonthChange);
    els.date.value = todayString();

    // 未指定月份時由伺服器決定本月
    api('GET', 'api/summary').then(function (s) {
      var m = typeof s.month === 'string' && /^\d{4}-\d{2}$/.test(s.month)
        ? s.month : todayString().slice(0, 7);
      state.month = m;
      els.month.value = m;
      els.date.value = defaultDateForMonth();
      renderSummary(s);
      return loadEntries();
    }).catch(function (err) {
      state.month = todayString().slice(0, 7);
      els.month.value = state.month;
      reportError(err);
    });
  }

  init();
})();

